"""Independent protocol verifier used for local testing only.

Replays the documented state machine using only reported response values and
checks every structural, state-identity and certificate requirement.
"""
import math
import numpy as np


def tol(a, b):
    return 1e-7 + 1e-7 * max(abs(a), abs(b))


def isnum(v):
    return type(v) in (int, float) and math.isfinite(v)


def avail_slots(paths_k, caps):
    out = []
    for p, path in enumerate(paths_k):
        if path is None:
            continue
        if all(caps[e] > 0 for e in path):
            out.append(p)
    return out


class CaseVerifier:
    def __init__(self, case):
        self.case = case
        self.E = len(case["edges"])
        self.K = len(case["commodities"])
        self.W = len(case["workers"])
        self.workers = [list(w) for w in case["workers"]]
        self.caps = [float(e[2]) for e in case["edges"]]
        self.demand = [float(c["demand"]) for c in case["commodities"]]
        self.paths = [list(c["paths"]) for c in case["commodities"]]
        self.alpha = case["relax"][0] / case["relax"][1]
        self.quorum = case["quorum"]
        self.max_lag = case["max_lag"]
        self.rho = int(case["rho"])
        self.mode = case["mode"]
        self.g = 0
        self.r = 0
        self.z = [0.0] * self.E
        self.u = [0.0] * self.E
        self.A = [[0.0] * self.E for _ in range(self.W)]
        self.flow = [[0.0] * len(p) for p in self.paths]
        self.seen = set()
        self.fresh = set()
        self.last_round = {}
        self.latest_seq = {}
        self.tickets = {}
        self.receipts = set()
        self.seq = 0
        self.errors = []
        self.live = lambda: [e for e in range(self.E) if self.caps[e] > 0]

    def err(self, msg):
        self.errors.append(msg)

    def exact_keys(self, obj, names, where):
        if type(obj) is not dict:
            self.err("%s: not an object" % where)
            return False
        if set(obj) != set(names.split()):
            self.err("%s: keys %s != %s" % (where, sorted(obj), sorted(names.split())))
            return False
        return True

    def numvec(self, seq, n, where, lo=-1e9, hi=1e9):
        if type(seq) is not list or len(seq) != n:
            self.err("%s: bad vector length %s" % (where, len(seq) if type(seq) is list else type(seq)))
            return False
        for v in seq:
            if not isnum(v):
                self.err("%s: non-number %r" % (where, v))
                return False
            if not lo - 1e-12 <= v <= hi + 1e-12:
                self.err("%s: out of range %r" % (where, v))
                return False
        return True

    def idlist(self, seq, where):
        if type(seq) is not list:
            self.err("%s: not a list" % where)
            return False
        for v in seq:
            if type(v) is not int or not 0 <= v < self.W:
                self.err("%s: bad id %r" % (where, v))
                return False
        if seq != sorted(set(seq)):
            self.err("%s: not strictly increasing" % where)
        return True

    def Xvec(self):
        X = [0.0] * self.E
        for e in self.live():
            X[e] = sum(self.A[w][e] for w in range(self.W)) / self.caps[e]
        return X

    def check(self, resp):
        if type(resp) is not dict or set(resp) != {"events"}:
            self.err("case response keys")
            return self.errors
        events = resp["events"]
        if type(events) is not list or len(events) != len(self.case["events"]):
            self.err("event count mismatch")
            return self.errors
        for ev, out in zip(self.case["events"], events):
            op = ev["op"]
            handler = getattr(self, "_" + op)
            handler(ev, out)
        return self.errors

    # ------------------------------------------------------------------ events
    def _configure(self, ev, out):
        if not self.exact_keys(out, "op generation", "configure"):
            return
        if out["op"] != "configure":
            self.err("configure op tag")
        self.mode = ev["mode"]
        for eid, cap in ev["capacity"]:
            self.caps[eid] = float(cap)
        for cid, dem in ev["demand"]:
            self.demand[cid] = float(dem)
        for cid, slot, path in ev["paths"]:
            self.paths[cid][slot] = None if path is None else list(path)
        self.g += 1
        self.r = 0
        self.z = [0.0] * self.E
        self.u = [0.0] * self.E
        self.A = [[0.0] * self.E for _ in range(self.W)]
        self.flow = [[0.0] * len(p) for p in self.paths]
        self.seen = set()
        self.fresh = set()
        self.last_round = {}
        self.latest_seq = {}
        if out["generation"] != self.g:
            self.err("configure generation %r != %d" % (out["generation"], self.g))

    def _issue(self, ev, out):
        if not self.exact_keys(out, "op id worker generation bias rho result", "issue"):
            return
        tid, w = ev["id"], ev["worker"]
        if out["op"] != "issue" or out["id"] != tid or out["worker"] != w:
            self.err("issue tags")
        if out["generation"] != self.g:
            self.err("issue generation")
        if out["rho"] != self.rho:
            self.err("issue rho")
        if not self.numvec(out["bias"], self.E, "issue bias"):
            return
        # bias identity
        X = self.Xvec()
        for e in range(self.E):
            want = 0.0
            if self.caps[e] > 0:
                want = self.A[w][e] / self.caps[e] + (self.z[e] - X[e] - self.u[e]) / self.W
            if abs(out["bias"][e] - want) > tol(out["bias"][e], want):
                self.err("bias[%d] %r vs %r" % (e, out["bias"][e], want))
        B = list(out["bias"])
        owned = self.workers[w]
        proposal = out["result"]
        avail = {k: avail_slots(self.paths[k], self.caps) for k in owned}
        unroutable = [k for k in owned if self.demand[k] > 0 and not avail[k]]
        if self.mode == "route" and unroutable:
            if type(proposal) is not dict or set(proposal) != {"status", "unroutable"}:
                self.err("infeasible proposal keys")
                return
            if proposal["status"] != "infeasible":
                self.err("expected infeasible")
            if proposal["unroutable"] != unroutable:
                self.err("unroutable list %r != %r" % (proposal["unroutable"], unroutable))
            self.tickets[tid] = {"seq": self.seq, "worker": w, "proposal": proposal}
            self.seq += 1
            return
        if type(proposal) is not dict or set(proposal) != {"status", "flow", "edge_load", "potential"}:
            self.err("optimal proposal keys")
            return
        if proposal["status"] != "optimal":
            self.err("expected optimal")
            return
        flow = proposal["flow"]
        if type(flow) is not list or len(flow) != len(owned):
            self.err("flow rows")
            return
        x = {}
        for i, k in enumerate(owned):
            row = flow[i]
            if type(row) is not list or len(row) != len(self.paths[k]):
                self.err("flow row length for commodity %d" % k)
                return
            for p, v in enumerate(row):
                if not isnum(v) or not -1e-12 <= v <= 1e9:
                    self.err("flow value %r" % v)
                    return
                if p not in avail[k] or self.demand[k] <= 0:
                    if v != 0:
                        self.err("forced zero slot (%d,%d) = %r" % (k, p, v))
                x[(k, p)] = float(v)
        # loads
        L = [0.0] * self.E
        for k in owned:
            for p, path in enumerate(self.paths[k]):
                v = x[(k, p)]
                if v == 0.0:
                    continue
                for e in path:
                    L[e] += v
        if not self.numvec(proposal["edge_load"], self.E, "edge_load", 0.0, 1e9):
            return
        for e in range(self.E):
            if self.caps[e] <= 0 and proposal["edge_load"][e] != 0:
                self.err("withdrawn edge load %d = %r" % (e, proposal["edge_load"][e]))
            if abs(proposal["edge_load"][e] - L[e]) > tol(proposal["edge_load"][e], L[e]):
                self.err("edge_load[%d] %r != %r" % (e, proposal["edge_load"][e], L[e]))
        # demand constraints
        for k in owned:
            s = sum(x[(k, p)] for p in range(len(self.paths[k])))
            if self.mode == "route":
                if abs(s - self.demand[k]) > tol(s, self.demand[k]):
                    self.err("route sum %d: %r != %r" % (k, s, self.demand[k]))
            else:
                if s > self.demand[k] + tol(s, self.demand[k]):
                    self.err("admit sum %d: %r > %r" % (k, s, self.demand[k]))
        # potentials
        pot = proposal["potential"]
        if type(pot) is not list or len(pot) != len(owned):
            self.err("potential length")
            return
        for v in pot:
            if not isnum(v) or not -1e9 <= v <= 1e9:
                self.err("potential value %r" % v)
                return
        for i, k in enumerate(owned):
            if self.demand[k] <= 0 and pot[i] != 0:
                self.err("zero-demand potential %d = %r" % (k, pot[i]))
            if self.mode == "admit" and pot[i] < -tol(pot[i], 0.0):
                self.err("admit potential negative %r" % pot[i])
        # derivative and certificate
        rho = self.rho
        admit = self.mode == "admit"
        G = {}
        for k in owned:
            if self.demand[k] <= 0:
                continue
            for p in avail[k]:
                g = x[(k, p)]
                for e in self.paths[k][p]:
                    g += rho * (L[e] / self.caps[e] - B[e]) / self.caps[e]
                if admit:
                    g -= 1.0
                G[(k, p)] = g
        for i, k in enumerate(owned):
            for p in avail[k]:
                if self.demand[k] <= 0:
                    continue
                val = G[(k, p)] + pot[i]
                if val < -tol(val, 0.0):
                    self.err("G+lambda<0 for (%d,%d): %r" % (k, p, val))
        f = 0.5 * sum(v * v for v in x.values())
        for e in self.live():
            f += 0.5 * rho * (L[e] / self.caps[e] - B[e]) ** 2
        if admit:
            f -= sum(x.values())
        D = f
        for (k, p), g in G.items():
            D -= x[(k, p)] * g
        for i, k in enumerate(owned):
            D -= self.demand[k] * pot[i]
        if abs(f - D) > tol(f, D):
            self.err("f != D: %r vs %r (diff %r)" % (f, D, f - D))
        self.tickets[tid] = {"seq": self.seq, "worker": w, "proposal": proposal}
        self.seq += 1

    def _deliver(self, ev, out):
        if not self.exact_keys(out, "op id status", "deliver"):
            return
        tid = ev["id"]
        if out["op"] != "deliver" or out["id"] != tid:
            self.err("deliver tags")
        t = self.tickets[tid]
        w = t["worker"]
        if tid in self.receipts:
            status = "duplicate"
        elif t["gen"] != self.g if False else self._ticket_gen(tid) != self.g:
            status = "obsolete"
        elif self.latest_seq.get(w, -1) > t["seq"]:
            status = "superseded"
        elif t["proposal"]["status"] != "optimal":
            status = "infeasible"
        else:
            status = "accepted"
        if out["status"] != status:
            self.err("deliver status %r != %r" % (out["status"], status))
        self.receipts.add(tid)
        if status == "accepted":
            prop = t["proposal"]
            for i, k in enumerate(self.workers[w]):
                self.flow[k] = [float(v) for v in prop["flow"][i]]
            self.A[w] = [float(v) for v in prop["edge_load"]]
            self.latest_seq[w] = t["seq"]
            self.seen.add(w)
            self.fresh.add(w)
            self.last_round[w] = self.r

    def _ticket_gen(self, tid):
        return self.tickets[tid]["gen"]

    def _step(self, ev, out):
        stale = [w for w in sorted(self.seen) if self.r - self.last_round[w] > self.max_lag]
        missing = [w for w in range(self.W) if w not in self.seen]
        blocked = bool(missing) or bool(stale) or len(self.fresh) < self.quorum
        if blocked:
            if not self.exact_keys(out, "op status missing stale fresh", "step-wait"):
                return
            if out["status"] != "waiting":
                self.err("step status")
            if out["missing"] != missing:
                self.err("missing %r != %r" % (out["missing"], missing))
            if out["stale"] != stale:
                self.err("stale %r != %r" % (out["stale"], stale))
            if out["fresh"] != sorted(self.fresh):
                self.err("fresh %r != %r" % (out["fresh"], sorted(self.fresh)))
            self.idlist(out["missing"], "missing")
            self.idlist(out["stale"], "stale")
            self.idlist(out["fresh"], "fresh")
            return
        if not self.exact_keys(out, "op status round load ceiling z dual pressure", "step-adv"):
            return
        if out["status"] != "advanced":
            self.err("step status")
        live = self.live()
        X = self.Xvec()
        z0 = list(self.z)
        u0 = list(self.u)
        V = [0.0] * self.E
        for e in live:
            V[e] = self.alpha * X[e] + (1 - self.alpha) * z0[e] + u0[e]
        rho = self.rho
        if not self.numvec(out["load"], self.E, "load", 0.0, 1e9):
            return
        S = [sum(self.A[w][e] for w in range(self.W)) for e in range(self.E)]
        for e in range(self.E):
            if abs(out["load"][e] - S[e]) > tol(out["load"][e], S[e]):
                self.err("load[%d] %r != %r" % (e, out["load"][e], S[e]))
        if not isnum(out["ceiling"]) or not -1e-12 <= out["ceiling"] <= 1e9:
            self.err("ceiling %r" % out["ceiling"])
            return
        h = float(out["ceiling"])
        if not self.numvec(out["z"], self.E, "z"):
            return
        if not self.numvec(out["dual"], self.E, "dual"):
            return
        if not self.numvec(out["pressure"], self.E, "pressure", 0.0, 1e9):
            return
        z = [float(v) for v in out["z"]]
        u = [float(v) for v in out["dual"]]
        t = [float(v) for v in out["pressure"]]
        for e in range(self.E):
            if self.caps[e] <= 0:
                if z[e] != 0 or u[e] != 0 or t[e] != 0:
                    self.err("withdrawn controller vector %d" % e)
                continue
            if abs(rho * (z[e] - V[e]) + t[e]) > tol(rho * (z[e] - V[e]), 0.0):
                self.err("pressure identity %d: %r" % (e, rho * (z[e] - V[e]) + t[e]))
            if abs(t[e] * (h - z[e])) > tol(t[e] * (h - z[e]), 0.0):
                self.err("complementarity %d: %r" % (e, t[e] * (h - z[e])))
            want = u0[e] + self.alpha * X[e] + (1 - self.alpha) * z0[e] - z[e]
            if abs(u[e] - want) > tol(u[e], want):
                self.err("dual update %d: %r != %r" % (e, u[e], want))
            if z[e] > h + tol(z[e], h):
                self.err("z > ceiling at %d" % e)
        if self.mode == "route":
            if h < -tol(h, 0.0):
                self.err("negative ceiling")
            gap = 1.0 - sum(t[e] for e in live)
            if gap < -tol(gap, 0.0):
                self.err("1 - sum t = %r" % gap)
            if h > tol(h, 0.0) and abs(gap) > tol(gap, 0.0):
                self.err("h*(1-sum t) != 0: h=%r gap=%r" % (h, gap))
        else:
            if abs(h - 1.0) > tol(h, 1.0):
                self.err("admit ceiling %r" % h)
        if out["round"] != self.r + 1:
            self.err("round %r != %d" % (out["round"], self.r + 1))
        self.r += 1
        self.z = z
        self.u = u
        self.fresh = set()

    def _retune(self, ev, out):
        if not self.exact_keys(out, "op rho", "retune"):
            return
        new = int(ev["rho"])
        old = self.rho
        for e in range(self.E):
            want = self.u[e] * old / new
            if abs(self.u[e] - want) > tol(self.u[e], want):
                # dual must have been rescaled
                pass
        self.u = [v * old / new for v in self.u]
        self.rho = new
        if out["rho"] != new:
            self.err("retune rho")

    def _save(self, ev, out):
        if not self.exact_keys(out, "op name", "save"):
            return
        self.snap = self._snapshot()
        if out["name"] != ev["name"]:
            self.err("save name")
        self.checkpoints = getattr(self, "checkpoints", {})
        self.checkpoints[ev["name"]] = self.snap

    def _snapshot(self):
        return {
            "caps": list(self.caps), "demand": list(self.demand),
            "paths": [list(p) for p in self.paths], "mode": self.mode,
            "rho": self.rho, "r": self.r, "z": list(self.z), "u": list(self.u),
            "A": [list(a) for a in self.A],
            "flow": [list(f) for f in self.flow],
            "seen": set(self.seen), "fresh": set(self.fresh),
            "last_round": dict(self.last_round),
            "latest_seq": dict(self.latest_seq),
        }

    def _restore(self, ev, out):
        if not self.exact_keys(out, "op name generation", "restore"):
            return
        snap = self.checkpoints[ev["name"]]
        self.caps = list(snap["caps"])
        self.demand = list(snap["demand"])
        self.paths = [list(p) for p in snap["paths"]]
        self.mode = snap["mode"]
        self.rho = snap["rho"]
        self.r = snap["r"]
        self.z = list(snap["z"])
        self.u = list(snap["u"])
        self.A = [list(a) for a in snap["A"]]
        self.flow = [list(f) for f in snap["flow"]]
        self.seen = set(snap["seen"])
        self.fresh = set(snap["fresh"])
        self.last_round = dict(snap["last_round"])
        self.latest_seq = dict(snap["latest_seq"])
        self.g += 1
        if out["name"] != ev["name"]:
            self.err("restore name")
        if out["generation"] != self.g:
            self.err("restore generation %r != %d" % (out["generation"], self.g))

    def _audit(self, ev, out):
        if not self.exact_keys(out, "op generation round rho flow worker_load load z dual seen fresh age", "audit"):
            return
        if out["generation"] != self.g:
            self.err("audit generation")
        if out["round"] != self.r:
            self.err("audit round")
        if out["rho"] != self.rho:
            self.err("audit rho")
        if type(out["flow"]) is not list or len(out["flow"]) != self.K:
            self.err("audit flow rows")
            return
        for k in range(self.K):
            row = out["flow"][k]
            if type(row) is not list or len(row) != len(self.paths[k]):
                self.err("audit flow row %d" % k)
                return
            for p, v in enumerate(row):
                if not isnum(v) or not -1e-12 <= v <= 1e9:
                    self.err("audit flow value")
                    return
                if abs(v - self.flow[k][p]) > tol(v, self.flow[k][p]):
                    self.err("audit flow[%d][%d] %r != %r" % (k, p, v, self.flow[k][p]))
        wl = out["worker_load"]
        if type(wl) is not list or len(wl) != self.W:
            self.err("audit worker_load rows")
            return
        for w in range(self.W):
            if type(wl[w]) is not list or len(wl[w]) != self.E:
                self.err("audit worker_load row %d" % w)
                return
            for e, v in enumerate(wl[w]):
                if not isnum(v) or not -1e-12 <= v <= 1e9:
                    self.err("audit worker_load value")
                    return
                if abs(v - self.A[w][e]) > tol(v, self.A[w][e]):
                    self.err("audit worker_load[%d][%d] %r != %r" % (w, e, v, self.A[w][e]))
        if not self.numvec(out["load"], self.E, "audit load", 0.0, 1e9):
            return
        S = [sum(self.A[w][e] for w in range(self.W)) for e in range(self.E)]
        for e in range(self.E):
            if abs(out["load"][e] - S[e]) > tol(out["load"][e], S[e]):
                self.err("audit load[%d]" % e)
        if not self.numvec(out["z"], self.E, "audit z"):
            return
        if not self.numvec(out["dual"], self.E, "audit dual"):
            return
        for e in range(self.E):
            if abs(out["z"][e] - self.z[e]) > tol(out["z"][e], self.z[e]):
                self.err("audit z[%d]" % e)
            if abs(out["dual"][e] - self.u[e]) > tol(out["dual"][e], self.u[e]):
                self.err("audit dual[%d]" % e)
        self.idlist(out["seen"], "audit seen")
        self.idlist(out["fresh"], "audit fresh")
        if out["seen"] != sorted(self.seen):
            self.err("audit seen %r != %r" % (out["seen"], sorted(self.seen)))
        if out["fresh"] != sorted(self.fresh):
            self.err("audit fresh %r != %r" % (out["fresh"], sorted(self.fresh)))
        age = out["age"]
        if type(age) is not list or len(age) != self.W:
            self.err("audit age length")
            return
        for w in range(self.W):
            if w not in self.seen:
                if age[w] is not None:
                    self.err("audit age[%d] should be null" % w)
            else:
                if age[w] != self.r - self.last_round[w]:
                    self.err("audit age[%d] %r != %d" % (w, age[w], self.r - self.last_round[w]))


def verify(request, response):
    errors = []
    if type(response) is not dict or set(response) != {"cases"}:
        return ["response keys"]
    if type(response["cases"]) is not list or len(response["cases"]) != len(request["cases"]):
        return ["case count"]
    for case, cres in zip(request["cases"], response["cases"]):
        sub = CaseVerifier(case).check(cres)
        if sub:
            errors.append({"case": case, "errors": sub})
    return errors
